int main(){std::ifstream f("/home/imo/HeCBench_julia/src/aes-julia/study_fixture.txt");std::map<std::string,std::string>fields;std::string k,v;while(f>>k>>v)fields[k]=v;auto plain=hexdata(fields["plain"]),cipher=hexdata(fields["cipher"]),expectedkey=hexdata(fields["roundkey"]),key=hexdata(fields["key"]);uchar expanded[176],rkey[176];keyExpansion(key.data(),expanded,16,176);for(int i=0;i<11;i++)createRoundKey(expanded+i*16,rkey+i*16);if(memcmp(rkey,expectedkey.data(),176))return 3;std::vector<uchar>check(4096);reference(check.data(),plain.data(),rkey,176,64,64,false,10,16);if(check!=cipher)return 4;reference(check.data(),cipher.data(),rkey,176,64,64,true,10,16);if(check!=plain)return 5;uchar *dp,*dc,*dy,*dk,*ds,*di;cudaMalloc(&dp,4096);cudaMalloc(&dc,4096);cudaMalloc(&dy,4096);cudaMalloc(&dk,176);cudaMalloc(&ds,256);cudaMalloc(&di,256);cudaMemcpy(dp,plain.data(),4096,cudaMemcpyHostToDevice);cudaMemcpy(dc,cipher.data(),4096,cudaMemcpyHostToDevice);cudaMemcpy(dk,rkey,176,cudaMemcpyHostToDevice);cudaMemcpy(ds,sbox,256,cudaMemcpyHostToDevice);cudaMemcpy(di,rsbox,256,cudaMemcpyHostToDevice);auto run=[&](int inverse){if(inverse)AESDecrypt<<<dim3(16,16),dim3(1,4)>>>((uchar4*)dy,(uchar4*)dc,(uchar4*)dk,di,64,10);else AESEncrypt<<<dim3(16,16),dim3(1,4)>>>((uchar4*)dy,(uchar4*)dp,(uchar4*)dk,ds,64,10);};run(0);run(1);if(cudaDeviceSynchronize()!=cudaSuccess)return 2;for(int trial=1;trial<=5;trial++){double total=0;bool ok=true;std::vector<uchar>out(8192);for(int mode=0;mode<2;mode++){cudaDeviceSynchronize();auto t=std::chrono::steady_clock::now();for(int j=0;j<10;j++)run(mode);if(cudaDeviceSynchronize()!=cudaSuccess)return 2;total+=std::chrono::duration<double>(std::chrono::steady_clock::now()-t).count()/10;cudaMemcpy(out.data()+mode*4096,dy,4096,cudaMemcpyDeviceToHost);auto&want=mode?plain:cipher;ok=ok&&memcmp(out.data()+mode*4096,want.data(),4096)==0;}char path[64];snprintf(path,sizeof(path),"trial_%d.bin",trial);FILE*f=fopen(path,"wb");fwrite(out.data(),1,out.size(),f);fclose(f);printf("STUDY_TRIAL {\"trial\":%d,\"time_seconds\":%.15g,\"correct\":%s,\"checked_values\":8192,\"max_abs_error\":%d,\"timing_region\":\"sum_encrypt_decrypt_bulk_kernel_means\",\"jit_excluded\":true,\"internal_repeats\":10,\"output_artifact\":{\"path\":\"%s\",\"dtype\":\"uint8\",\"count\":8192,\"byte_order\":\"little\"}}\n",trial,total,ok?"true":"false",ok?0:1,path);if(!ok)return 1;}cudaFree(dp);cudaFree(dc);cudaFree(dy);cudaFree(dk);cudaFree(ds);cudaFree(di);}
